-- 20261021c — Câu mẫu cố định: thêm 23 câu nguyên văn có từ trước khi theo bản anh Luận (SRS-5.1zzzzzzz110). Chủ dự án 21/10/2026:
-- "đưa luôn mấy câu trước đó nữa đi" — chào / làm mới phiên, dòng mở + câu hỏi cuối bản nháp, ẩn / giữ rổ hàng, nhận ảnh, link / file không
-- mở được, bản vẽ, bảng tính, tin nhắc 5 phút. Dòng sinh từ cau_mau.MAC_DINH; dòng đã có thì chỉ làm mới câu gốc / mô tả, KHÔNG đụng câu
-- chủ dự án đã sửa (cột cau).
insert into public.cau_mau (khoa, cau, mac_dinh, dung_o, nguon, thu_tu) values
  ('chao_lan_dau', 'Chào {goi} ạ! Em là {ten}, trợ lý bất động sản của AI Ơi Nhà Đất. 🏡✨
{Goi} đang có căn chung cư, nhà phố hay đất cần gửi bán hoặc cho thuê vậy ạ?', 'Chào {goi} ạ! Em là {ten}, trợ lý bất động sản của AI Ơi Nhà Đất. 🏡✨
{Goi} đang có căn chung cư, nhà phố hay đất cần gửi bán hoặc cho thuê vậy ạ?', 'Khách chào (hello / hi / alo / 👋) lần đầu. {ten} = tên trợ lý', 'Lời chào cũ, giữ (quyết định 20/10)', 9),
  ('chao_lam_moi', 'Chào {goi} ạ! Em là {ten}, trợ lý bất động sản của AI Ơi Nhà Đất. 🏡✨
Em đã làm mới cuộc trò chuyện rồi ạ. {Goi} đang có căn chung cư, nhà phố hay đất cần gửi bán hoặc cho thuê vậy ạ?', 'Chào {goi} ạ! Em là {ten}, trợ lý bất động sản của AI Ơi Nhà Đất. 🏡✨
Em đã làm mới cuộc trò chuyện rồi ạ. {Goi} đang có căn chung cư, nhà phố hay đất cần gửi bán hoặc cho thuê vậy ạ?', 'Khách chào khi đã có chuyện cũ — làm mới phiên. {ten} = tên trợ lý', 'Quyết định 20/10: hello làm mới phiên', 10),
  ('lenh_lam_moi', 'Em chào {goi}! Em là {ten} từ AI Ơi Nhà Đất.
Em đã làm mới phiên chat và xóa toàn bộ thông tin nháp trước đó rồi ạ. {Goi} có thể bắt đầu gửi thông tin nhà đất cần rao bán hoặc cho thuê nhé! 🏡✨', 'Em chào {goi}! Em là {ten} từ AI Ơi Nhà Đất.
Em đã làm mới phiên chat và xóa toàn bộ thông tin nháp trước đó rồi ạ. {Goi} có thể bắt đầu gửi thông tin nhà đất cần rao bán hoặc cho thuê nhé! 🏡✨', 'Lệnh /reset, /xoa, "xóa hết". {ten} = tên trợ lý', 'Lệnh thử của chủ dự án', 11),
  ('mo_dau_nhap', '📋 Em sẽ rao như vầy nhé {goi}:', '📋 Em sẽ rao như vầy nhé {goi}:', 'Dòng mở bản nháp tin rao — phải bắt đầu 📋 và kết thúc dấu ":" (code cắt câu dẫn theo dòng này)', 'SRS-5.1zzzzzzz76 / 85 / 90', 12),
  ('mo_dau_nhap_em', '📋 Mình sẽ rao như vầy nhé em:', '📋 Mình sẽ rao như vầy nhé em:', 'Như trên, khi khách xưng "em" — phải bắt đầu 📋, kết thúc ":"', 'SRS-5.1zzzzzzz76', 13),
  ('hoi_ban_nhap', '{Goi} thấy bản tin này hấp dẫn chưa ạ?', '{Goi} thấy bản tin này hấp dẫn chưa ạ?', 'Câu hỏi cuối bản nháp (bot được dặn kết bản nháp bằng câu này)', 'Kịch bản người bán', 14),
  ('hoi_ban_nhap_em', 'Em thấy bản tin này hấp dẫn chưa?', 'Em thấy bản tin này hấp dẫn chưa?', 'Như trên, khi khách xưng "em"', 'Kịch bản người bán', 15),
  ('xac_nhan_an', '{Goi} muốn em **{viec}** — đúng không ạ? Nhắn **"đúng"** để em làm, hoặc **"thôi"** để giữ nguyên nhé. (Em KHÔNG xóa dữ liệu đâu — chỉ ẩn tin, rao lại lúc nào cũng được.)', '{Goi} muốn em **{viec}** — đúng không ạ? Nhắn **"đúng"** để em làm, hoặc **"thôi"** để giữ nguyên nhé. (Em KHÔNG xóa dữ liệu đâu — chỉ ẩn tin, rao lại lúc nào cũng được.)', 'Khách bảo gỡ / ẩn căn — hỏi xác nhận trước. {viec} = việc sắp làm (vd "NGƯNG RAO căn A12")', 'Hỏi trước khi ẩn', 16),
  ('da_an_het', 'Em đã NGƯNG RAO toàn bộ rổ hàng ạ — các tin giờ ở trạng thái **không rao** (em vẫn giữ nguyên dữ liệu, {goi} muốn rao lại căn nào cứ nhắn em). 🙈', 'Em đã NGƯNG RAO toàn bộ rổ hàng ạ — các tin giờ ở trạng thái **không rao** (em vẫn giữ nguyên dữ liệu, {goi} muốn rao lại căn nào cứ nhắn em). 🙈', 'Khách đồng ý ẩn hết', 'Hỏi trước khi ẩn', 17),
  ('da_an_bot', 'Em đã cập nhật — giờ còn **{n} căn đang rao** ạ. Các căn kia em chuyển sang **không rao** (vẫn giữ dữ liệu, rao lại được bất cứ lúc nào nha). ✅', 'Em đã cập nhật — giờ còn **{n} căn đang rao** ạ. Các căn kia em chuyển sang **không rao** (vẫn giữ dữ liệu, rao lại được bất cứ lúc nào nha). ✅', 'Khách đồng ý ẩn bớt / chỉ giữ vài căn. {n} = số căn còn rao', 'Hỏi trước khi ẩn', 18),
  ('da_cap_nhat_ro', 'Em đã cập nhật rổ hàng rồi ạ.', 'Em đã cập nhật rổ hàng rồi ạ.', 'Khách đồng ý, việc khác ngoài ẩn', 'Hỏi trước khi ẩn', 19),
  ('giu_nguyen_ro', 'Em giữ nguyên rổ hàng, không xóa gì đâu ạ 👍', 'Em giữ nguyên rổ hàng, không xóa gì đâu ạ 👍', 'Khách không đồng ý ẩn', 'Hỏi trước khi ẩn', 20),
  ('nhan_anh', '📎 Em đã nhận {n} ảnh của nhà mình rồi nhé! 📸✨', '📎 Em đã nhận {n} ảnh của nhà mình rồi nhé! 📸✨', 'Dòng đầu khi khách gửi ảnh (tên file là mã máy). {n} = số ảnh', 'Nhận ảnh', 21),
  ('file_qua_lon', 'File to quá ạ (>20MB), xin lỗi em chưa xử lý được 😔. Em đã báo admin rồi ạ — {goi} không cần làm gì thêm đâu. Admin của em sẽ vào chat này đọc file/link của mình rồi xử lý sau nhé!', 'File to quá ạ (>20MB), xin lỗi em chưa xử lý được 😔. Em đã báo admin rồi ạ — {goi} không cần làm gì thêm đâu. Admin của em sẽ vào chat này đọc file/link của mình rồi xử lý sau nhé!', 'Khách gửi file / ảnh quá 20 MB — đã báo admin', 'Nhận tệp', 22),
  ('link_thu_muc_drive', 'Đây là link thư mục Drive ạ. {Goi} gửi từng ảnh/file (hoặc link từng tấm) giúp em nhé!', 'Đây là link thư mục Drive ạ. {Goi} gửi từng ảnh/file (hoặc link từng tấm) giúp em nhé!', 'Khách gửi link THƯ MỤC Google Drive (chưa đọc được)', 'Nhận tệp', 23),
  ('link_khong_mo_duoc', 'Em chưa mở được link này ạ. {Goi} chụp và gửi thẳng giúp em vài tấm nhé!', 'Em chưa mở được link này ạ. {Goi} chụp và gửi thẳng giúp em vài tấm nhé!', 'Khách gửi link ảnh / tệp không tải được', 'Nhận tệp', 24),
  ('link_web_trong', 'Em mở link nhưng chưa đọc được nội dung ạ 😅. {Goi} gửi link khác, hoặc dán nội dung giúp em nhé.', 'Em mở link nhưng chưa đọc được nội dung ạ 😅. {Goi} gửi link khác, hoặc dán nội dung giúp em nhé.', 'Khách gửi link trang web mà trang trống', 'Nhận tệp', 25),
  ('nhap_bang_tinh', 'Em nhận được bảng tính rồi, đã nhập {n} căn vào rổ hàng của mình ạ! 🎉 {Goi} xem lại giúp em nhé.', 'Em nhận được bảng tính rồi, đã nhập {n} căn vào rổ hàng của mình ạ! 🎉 {Goi} xem lại giúp em nhé.', 'Khách gửi link bảng tính (rổ hàng). {n} = số căn đã nhập', 'Nhận tệp', 26),
  ('bang_tinh_trong', 'Em có nhận bảng tính nhưng chưa đọc ra căn nào — {goi} kiểm tra lại các cột (loại hình, địa chỉ, diện tích, giá...) giúp em nhé.', 'Em có nhận bảng tính nhưng chưa đọc ra căn nào — {goi} kiểm tra lại các cột (loại hình, địa chỉ, diện tích, giá...) giúp em nhé.', 'Bảng tính không đọc ra căn nào', 'Nhận tệp', 27),
  ('chua_co_ban_ve', 'Em CHƯA có bản vẽ/mặt bằng {can} ạ 😅. {Goi} gửi giúp em file bản vẽ, hoặc để em xin bên dự án rồi gửi lại nhé! (Em không đụng gì tới rổ hàng đâu ạ.)', 'Em CHƯA có bản vẽ/mặt bằng {can} ạ 😅. {Goi} gửi giúp em file bản vẽ, hoặc để em xin bên dự án rồi gửi lại nhé! (Em không đụng gì tới rổ hàng đâu ạ.)', 'Khách xin bản vẽ / mặt bằng mà chưa có. {can} = căn đang nói (vd "căn A12 (mẫu Fusion)")', 'Bản vẽ', 28),
  ('nhac_hoi_lai', '{Goi} ơi, {toi} hỏi lại chút nha: {hoi}', '{Goi} ơi, {toi} hỏi lại chút nha: {hoi}', 'Tin nhắc sau 5 phút khách im — hỏi lại câu bot vừa hỏi. {toi} = em / mình, {hoi} = câu bot vừa hỏi', 'SRS-5.1zzzzzzz73', 29),
  ('nhac_xin_anh', 'Khi nào tiện {goi} chụp gửi em vài tấm ảnh thực tế nhé, để tin đăng nổi bật và hút khách hơn ạ.', 'Khi nào tiện {goi} chụp gửi em vài tấm ảnh thực tế nhé, để tin đăng nổi bật và hút khách hơn ạ.', 'Tin nhắc sau 5 phút khi không còn câu chờ và căn chưa có ảnh', 'SRS-5.1zzzzzzz73', 30),
  ('nhac_xin_anh_em', 'Khi nào tiện em chụp gửi mình vài tấm ảnh thực tế nhé, để tin đăng nổi bật và hút khách hơn nè.', 'Khi nào tiện em chụp gửi mình vài tấm ảnh thực tế nhé, để tin đăng nổi bật và hút khách hơn nè.', 'Như trên, khi khách xưng "em"', 'SRS-5.1zzzzzzz73', 31)
on conflict (khoa) do update set mac_dinh = excluded.mac_dinh, dung_o = excluded.dung_o, nguon = excluded.nguon, thu_tu = excluded.thu_tu;
